<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
import {useRouter,RouterLink} from 'vue-router'
import {onAuthStateChanged} from 'firebase/auth'
import type {QueryDocumentSnapshot} from 'firebase/firestore'
import {getStagingClients} from '../integrations/firebase/stagingClient'
import {mayWriteLive} from '../integrations/firebase/stagingConfig'
import {verifyPlatformAccess} from '../integrations/firebase/platformAccess'
import {listPlatformGyms,platformCounts,getBillingExemption,setBillingExemption,type PlatformGym} from '../integrations/firestore/platform'
import BillingSandbox from '../components/BillingSandbox.vue'
import {billingSandboxEnabled} from '../integrations/firebase/billingSandbox'
import SupportTickets from '../components/SupportTickets.vue'
const router=useRouter(),allowed=ref(false),busy=ref(false),error=ref(''),tab=ref<'gyms'|'tickets'|'billing'>('gyms'),gyms=ref<PlatformGym[]>([]),counts=ref<{gyms:number;tickets:number}|null>(null),more=ref(false),selected=ref<PlatformGym|null>(null),exempt=ref(false),exemptReady=ref(false)
let alive=true,cursor:QueryDocumentSnapshot|undefined,stop:(()=>void)|undefined
async function load(append=false){if(busy.value||!allowed.value)return;busy.value=true;error.value='';try{const data=await listPlatformGyms(append?cursor:undefined);if(!alive)return;gyms.value=[...(append?gyms.value:[]),...data.rows];cursor=data.cursor;more.value=data.more;counts.value=await platformCounts()}catch(e){if(alive)error.value=(e as Error).message}finally{busy.value=false}}
async function pick(g:PlatformGym){if(busy.value)return;selected.value=g;exemptReady.value=false;busy.value=true;error.value='';try{exempt.value=await getBillingExemption(g.id);exemptReady.value=true}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function save(){if(!selected.value||!exemptReady.value||busy.value)return;if(!window.confirm('Salvare la preferenza commerciale di esenzione? Non modifica l’accesso o i pagamenti attuali.'))return;busy.value=true;error.value='';try{await setBillingExemption(selected.value.id,exempt.value);error.value='Preferenza esenzione salvata. Nessun addebito o sospensione attivati.'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(async()=>{if(!await verifyPlatformAccess()){void router.replace('/impostazioni');return}if(!alive)return;const {auth}=getStagingClients(),id=auth.currentUser?.uid;stop=onAuthStateChanged(auth,u=>{if(u?.uid!==id){allowed.value=false;gyms.value=[];selected.value=null;counts.value=null;void router.replace('/accesso')}});allowed.value=true;void load()})
onUnmounted(()=>{alive=false;stop?.()})
</script>
<template><div v-if="allowed" class="stack lf14-platform"><header class="panel"><span class="eyebrow">LIONFIT · ACCESSO RISERVATO</span><h1>Control Center</h1><p class="muted">Amministrazione della piattaforma, separata dal ruolo di Coach.</p><RouterLink to="/impostazioni" class="secondary">Torna alle impostazioni</RouterLink></header><div class="lf14-platform-kpis"><section class="panel"><small>Palestre registrate</small><h2>{{counts?.gyms??'—'}}</h2></section><section class="panel"><small>Ticket da gestire</small><h2>{{counts?.tickets??'—'}}</h2></section></div><div class="row"><button :class="tab==='gyms'?'primary':'secondary'" @click="tab='gyms'">Palestre</button><button :class="tab==='tickets'?'primary':'secondary'" @click="tab='tickets'">Assistenza</button><button v-if="billingSandboxEnabled()" :class="tab==='billing'?'primary':'secondary'" @click="tab='billing'">Abbonamenti test</button></div><p v-if="error" class="notice" role="status">{{error}}</p><SupportTickets v-if="tab==='tickets'" platform/><section v-else-if="tab==='billing'&&billingSandboxEnabled()" class="stack"><label>Palestra da verificare (elenco caricato)<select :value="selected?.id||''" @change="selected=gyms.find(g=>g.id===($event.target as HTMLSelectElement).value)||null"><option value="">Solo catalogo</option><option v-for="g in gyms" :key="g.id" :value="g.id">{{g.name}}</option></select></label><BillingSandbox platform :gym-id="selected?.id"/></section><section v-else class="panel stack"><div class="row between"><h2>Palestre registrate</h2><button class="secondary" :disabled="busy" @click="load()">Aggiorna</button></div><p v-if="!gyms.length" class="muted">{{busy?'Caricamento…':'Nessuna palestra caricata.'}}</p><button v-for="g in gyms" :key="g.id" class="secondary lf14-ticket-row" :disabled="busy" @click="pick(g)"><span><strong>{{g.name}}</strong><small>{{g.id}}</small></span><span>{{g.createdAt?new Date(g.createdAt).toLocaleDateString('it-IT'):'—'}}</span></button><button v-if="more" class="secondary" :disabled="busy" @click="load(true)">Carica altre palestre</button><section v-if="selected" class="lf14-ticket-detail"><h3>{{selected.name}}</h3><p class="muted small">In produzione Stripe e sospensioni sono inattivi. Nessun dato privato degli atleti viene aperto da quest'area.</p><label v-if="exemptReady" class="lf14-toggle"><span>Esente dal futuro abbonamento LionFit</span><input type="checkbox" v-model="exempt" :disabled="busy"/></label><button class="primary" :disabled="!exemptReady||busy||!mayWriteLive()" @click="save">Salva preferenza</button></section></section></div><p v-else class="panel">Verifica autorizzazione piattaforma…</p></template>
